#!/usr/bin/env bash
# Self-extracting installer: unpacks upload-server and launches it immediately.
# Usage: bash install.sh
set -e

WORKDIR="$(pwd)"
EXTRACT_DIR="$WORKDIR/upload-server"
ZIP_PATH="$WORKDIR/.upload-server-payload.zip"

echo "==> Unpacking embedded payload..."
awk '/^__PAYLOAD_BELOW__$/{found=1; next} found' "$0" | base64 -d > "$ZIP_PATH"

if ! command -v unzip >/dev/null 2>&1; then
  echo "==> unzip not found, attempting install..."
  if command -v apt-get >/dev/null 2>&1; then
    if command -v sudo >/dev/null 2>&1; then SUDO="sudo"; else SUDO=""; fi
    $SUDO apt-get update -y && $SUDO apt-get install -y unzip
  elif command -v yum >/dev/null 2>&1; then
    if command -v sudo >/dev/null 2>&1; then SUDO="sudo"; else SUDO=""; fi
    $SUDO yum install -y unzip
  elif command -v brew >/dev/null 2>&1; then
    brew install unzip
  else
    echo "Error: install unzip manually and re-run."
    exit 1
  fi
fi

echo "==> Extracting to $EXTRACT_DIR ..."
unzip -o "$ZIP_PATH" -d "$WORKDIR" > /dev/null
rm -f "$ZIP_PATH"

echo "==> Launching..."
cd "$EXTRACT_DIR"
chmod +x start.sh
exec ./start.sh

exit 0
__PAYLOAD_BELOW__
